-- Mod-authored natural wonder portrait descriptions, ru_RU overlay.
-- Baseline in CivVAccess_NaturalWonderDescStrings_en_US.lua.
CivVAccess_Strings = CivVAccess_Strings or {}

CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_MISSING"] =
    "Описание этого чуда природы отсутствует."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_CRATER"] =
    "Огромный ударный кратер, видимый с его края, рваная чаша, выбитая в бледной пустынной земле. Ближний склон порос зелёным кустарником, который обрывается в затенённую яму, и дно её тонет в глубокой бурой тьме, а дальний край поднимается полосами охристого и золотого под подёрнутым дымкой небом."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_EL_DORADO"] =
    "Ступенчатая пирамида из чистого золота, по лицевой стороне которой к небольшому святилищу на вершине круто восходит лестница. Гигантские золотые слитки сложены у её основания среди тонких тёмных деревьев, и вся сцена сияет жёлтым, сокровища мифического города воплощены наяву. Лучи света позади неё похожи на рассвет, занимающийся над затерянным городом."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_FOUNTAIN_YOUTH"] =
    "Родник невероятно ярко-бирюзовой воды бьёт из чаши на вершине тёмных скал и низвергается светящимся водопадом в озерцо внизу. Пучки зелёной травы цепляются за чёрный камень, пальмовые ветви обрамляют тёплое золотое небо, а крошечные искры в воде выдают в нём волшебный, а не природный источник."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_FUJI"] =
    "Идеальный вулканический конус заполняет собой кадр, его широкая снежная шапка спускается почти до самого подножия склонов. Снег написан мягким белым и бледно-голубым на фоне густо-синего неба, а вдоль подножия горы тянется полоса зелёного кустарника и подёрнутой дымкой воды."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_GEYSER"] =
    "Гейзер бьёт из скалистого бледного бугра, его белый фонтан веером расходится так, что заполняет туманом всё небо на фоне синевы. С обеих сторон подступает тёмный хвойный лес, а на переднем плане лежит корка минеральных террас в охристых, жёлто-коричневых и бурых тонах."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_GIBRALTAR"] =
    "Огромный известняковый мыс поднимается из ровного моря, отвесные бледные утёсы на его левой стороне и длинный склон тёмно-зелёной растительности, сбегающий по его спине. Вся сцена залита золотом, небо и вода светятся, как в предвечерний час."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_KILIMANJARO"] =
    "Огромный, испещрённый снегом купол заполняет верхнюю половину кадра ледяным белым и голубым, и у его основания плывёт венец из небольших облаков. Ниже простирается зелёная саванна, где у бледного водопоя стоят два жирафа, а по краям сцены растут деревья с плоскими кронами."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_LAKE_VICTORIA"] =
    "Широкое бирюзовое озеро уходит вдаль к бледным холмам на горизонте, стиснутое скалистыми жёлто-коричневыми выступами с обеих сторон. В центре на переднем плане всплывает гиппопотам, его голова и спина разбивают подёрнутую рябью воду, под белым сиянием, заполняющим небо."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_MESA"] =
    "Плосковершинная столовая гора из слоистой красно-оранжевой породы поднимается особняком над сухой равниной, полосатые стены утёсов над длинными склонами осыпавшегося камня. Редкий зелёный кустарник усеивает песчаную землю у её подножия, а плоская вершина прочерчивает резкую линию на фоне яркого синего неба."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_MT_KAILASH"] =
    "Пирамида из полосатой породы и снега поднимается на фоне густо-синего неба, её исчерченная грань с одной стороны освещена тёплым золотом. Ниже передний план весь состоит из неровного снежного поля и ледяных гряд в холодной синей тени."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_MT_SINAI"] =
    "Скопление скалистых пустынных вершин из оранжево-бурого песчаника, глубокие промоины бороздят их склоны, и мягкое сияние пробивается из-за центральной вершины. Разбросанные валуны усеивают песчаную равнину на переднем плане под ясным синим небом."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_POTOSI"] =
    "Голая красновато-бурая гора, чьи нижние склоны погребены под грудами серых валунов, поблёскивающих серебряной рудой. По её боку вьётся тропа, ряды тёмных тёсаных блоков выстроились у её основания, словно горные выработки, а пыльная вершина возвышается на фоне синего неба."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_REEF"] =
    "Подводная сцена: кораллы теснятся в левой и нижней части кадра в оранжевых, красных, фиолетовых и бледно-голубых тонах, среди ветвей стоят прямые трубчатые губки. Маленькие тропические рыбки скользят сквозь густо-синюю воду, ярко-жёлтая в центре. К верхнему правому углу свет угасает, переходя в открытую тьму."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_SOLOMONS_MINES"] =
    "Монументальная надвратная башня, замещающая собой легендарные копи: высокая тёмная крепостная стена, увенчанная зубцами с золочёными остриями, дверной проём в её центре, по бокам жёлто-коричневые каменные башни. Перед ней бледный каменный пол высечен размашистыми изгибами, словно сама земля была гладко вырублена."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_SRI_PADA"] =
    "Пышная зелёная гора поднимается к округлой вершине, джунгли покрывают её склоны всюду, кроме мест, где наружу прорывается оранжево-бурая порода в виде утёсов. Высокие травинки с мелкими синими цветами заполняют передний план, а небо позади горит яркой тропической бирюзой."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_ULURU"] =
    "Огромный красный монолит лежит поперёк среднего плана, его округлая песчаниковая масса изборождена вертикальными ложбинами и пылает оранжевым в лучах света. Перед ним простирается плоский кустарник австралийской глубинки, красная земля, испещрённая низким зелёным кустарником и пучками травы, под ярким синим небом."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_NWDESC_FEATURE_VOLCANO"] =
    "Тёмный вулканический конус поднимается из моря за полосой бледно-бирюзовой воды, видимый с поросшего джунглями берега, чьи широкие зелёные листья обрамляют сцену. Небо над ним пылает сернисто-жёлтым, и слабый завиток дыма над вершиной намекает на грядущее извержение."
